def rot(q, n):
    to = ROT[n % 4] % len(q['opts'])
    o = q['opts'][:]; r = o.pop(q['ans']); o.insert(to, r); q['opts'] = o; q['ans'] = to

def apply_fix():
    # ปรับตัวเลือกให้ยาวใกล้กัน (คำตอบถูกอยู่ตัวแรก แล้วหมุนตำแหน่งทีหลัง)
    fx = json.loads((HERE / 'opts_fix_m3.json').read_text(encoding='utf-8'))
    for key, arr in fx.items():
        w, c, i = key.split('.'); c = int(c); i = int(i)
        q = PRACTICE[c]['items' if w == 'items' else 'battle'][i] if w in ('items', 'battle') else PREPOST[c][w][i]
        assert len(q['opts']) == len(arr) and q['ans'] == 0, key
        q['opts'] = arr

def main():
    apply_fix()
    n = 0
    for ch in PRACTICE.values():
        for q in ch['items']:
            if q['t'] == 'choice': rot(q, n); n += 1
        for q in ch['battle']: rot(q, n); n += 1
    n = 0
    for ch in PREPOST.values():
        for k in ('pre', 'post'):
            for q in ch[k]: rot(q, n); n += 1
    head = ('/* ด่านฝึก ม.3 การออกแบบและเทคโนโลยี — ตรวจอัตโนมัติ ไม่ต้องรอครู · สร้างจาก gas-dt-m3/practice_content.py ห้ามแก้มือ\n'
            '   ชนิดข้อ: choice · pick · sort · match · order · สถานการณ์จากหนังสือเรียน สสวท. และบ้านสวนลุงชัย (ข้อมูลสมมติ) */\n')
    (DST / 'practice-data.js').write_text(head + 'window.DT_PRACTICE = ' + json.dumps(PRACTICE, ensure_ascii=False, indent=1) + ';\n', encoding='utf-8')
    head = ('/* ข้อสอบวัดความรู้ก่อนเรียน/หลังเรียน ราย 3 บท · ม.3 · สร้างจาก gas-dt-m3/practice_content.py ห้ามแก้มือ\n'
            '   ข้อก่อนและหลังวัดทักษะเดียวกันด้วยสถานการณ์ใหม่ เพื่อเทียบพัฒนาการ */\n')
    (DST / 'prepost-data.js').write_text(head + 'window.DT_PREPOST = ' + json.dumps(PREPOST, ensure_ascii=False, indent=1) + ';\n', encoding='utf-8')
    for k, ch in PRACTICE.items():
        print('บท', k, 'ด่านฝึก', len(ch['items']), 'บอส', len(ch['battle']), 'ก่อน', len(PREPOST[k]['pre']), 'หลัง', len(PREPOST[k]['post']))

if __name__ == '__main__':
    main()
